('passage_reconstruction', '{"passage": "Tom had been planning a trip to the coast for months. The night before leaving, he discovered his car would not start. His neighbor offered to drive him to the train station instead. Tom made it just in time and enjoyed a relaxing weekend by the sea."}'::jsonb, '{"key_points": ["Tom planned a trip to the coast", "his car would not start", "a neighbor drove him to the station", "he enjoyed a relaxing weekend"]}'::jsonb, 50, 0.55, 'B2', 'approved', 'exam', 'travel', 'a2000000-0000-4000-8000-000000000016', 1),
('passage_reconstruction', '{"passage": "Hannah noticed her laptop was running very slowly. She called the technician, who suggested clearing old files first. After doing that, the laptop worked much faster. Hannah was relieved she did not need to buy a new one."}'::jsonb, '{"key_points": ["Hannah''s laptop was slow", "a technician suggested clearing old files", "the laptop worked faster afterward", "she did not need a new one"]}'::jsonb, 45, 0.55, 'B2', 'approved', 'exam', 'technology', 'a2000000-0000-4000-8000-000000000016', 2);
